/**
 * Records one row from an event payload: the actor and the time come from the
 * envelope, so a late-running handler still files the action when it happened.
 */
async function write(
  envelope: TaskflowEventMap["project.created"] | { orgId: OrgId; actorId: UserId | null; occurredAt: IsoTimestamp },
  action: ActivityAction,
  input: Omit<ActivityRecordInput, "actorId" | "occurredAt">,
): Promise<void> {
  await record(envelope.orgId, action, {
    ...input,
    actorId: envelope.actorId,
    occurredAt: envelope.occurredAt,
  });
}

/** A comment's project is its issue's project. */
async function commentProjectId(payload: {
  orgId: OrgId;
  issueId: TaskflowEventMap["comment.created"]["issueId"];
  projectId?: ProjectId;
}): Promise<ProjectId | null> {
  if (payload.projectId) return payload.projectId;
  const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
  return issue?.projectId ?? null;
}
